DROP VIEW IF EXISTS replset.vw_month_goods_remain CASCADE;  CREATE OR REPLACE VIEW replset.vw_month_goods_remain AS  SELECT date_trunc('month'::text, date_period) AS repmonth,     orgs_code,     orgs_name,     shop_code,     shop_name,     sum(amount) AS amount,     sum(amountman) AS amountman    FROM mvw_goods_remain   GROUP BY (date_trunc('month'::text, date_period)), orgs_code, orgs_name, shop_code, shop_name;
